pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint256[] memory v) public {
        // admissible domain: non-empty tos and matching lengths
        vm.assume(tos.length > 0 && tos.length == v.length && tos.length < 20);

        // Deploy a minimal callee that simply accepts the call (EOAs would also accept but have no code)
        // We deploy a benign callee so the low-level call returns (simulating normal counterparties).
        Callee cal = new Callee();

        // replace c.caddress is not possible (not exposed), but we can route inputs: the contract uses a fixed caddress field.
        // However, the intended difference is only the returned boolean; we only need transfer to complete.
        // Ensure msg.sender is the expected one.
        address sender = address(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        vm.deal(sender, 1 ether);
        vm.startPrank(sender);
        // The contract's caddress is fixed; calling transfer will perform low-level calls to that address.
        // Those calls may succeed or fail; to ensure completion we do not constrain behavior — we only assert the return value when call completes.

        bool ok;
        try c.transfer(tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, we consider this input inadmissible for our property and skip by returning early
            vm.stopPrank();
            return;
        }
        vm.stopPrank();

        // The universal property: whenever transfer completes, it must return true in the reference.
        // This single assertion is true for the reference and will fail on the mutant for some inputs.
        assertTrue(ok);
    }
}

// Minimal benign callee: accepts any call and returns true-ish data (does nothing)
contract Callee {
    fallback() external payable { }
}

