    function setUp() public { c = new C(); }

    // fuzz parameters: array of destination addresses and array of values
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // domain restrictions: must be same non-zero length and not exceed reasonable loop bound
        vm.assume(_tos.length > 0 && _tos.length == v.length && _tos.length <= 64);
        // ensure caller is the expected allowed sender
        address caller = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        // run the call and capture whether it completed (did not revert) and its returned boolean
        bool ok;
        bool ret;
        vm.prank(caller);
        try c.transfer(_tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false; // irrelevant when reverted
        }

        // The universal property: whenever transfer completes, it returns true in the reference implementation.
        // This is the single assertion required. The mutant that returns false will make this fail for some input.
        if (ok) {
            assertTrue(ret);
        } else {
            // if it reverted, we do not assert on return value; just assert true to keep single assert in reachable path
            // BUT per the rules we must have exactly one assertTrue reading c's behavior — the above is that assert
            // To satisfy single-assert requirement, we place the assert only in the path where call completed.
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: caller provides arrays and chooses caller via tx.origin-like pattern
    // We cannot change msg.sender here, but we can rely on c.transfer reverting for non-owner callers.
    // The function is external so an external account (the test harness) can call it as a non-owner.
    function run(address[] calldata tos, uint[] calldata vals) external {
        // Preconditions for sensible inputs
        require(tos.length == vals.length, "len");
        require(tos.length > 0, "nonempty");

        // We attempt the transfer as the current caller (msg.sender). On the original contract P,
        // transfer requires msg.sender == owner, so if this caller is not the owner it will revert.
        // On mutant M the require is removed and the call will succeed (returning true).
        // We capture the low-level return boolean by using try/catch on external call wrapper.

        bool success;
        try c.transfer(tos, vals) returns (bool r) {
            success = r;
        } catch {
            success = false;
        }

        // Assert that this call did not succeed unless the caller is the owner stored in c.from().
        // We read c.from() getter to compare.
        // This general rule holds on P (only owner can succeed) and is violated by M (any caller can succeed).
        assert(success == (msg.sender == c.from()));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] memory tos, uint[] memory vals) public payable {
        // require non-empty recipients to exercise loop and require in original
        require(tos.length > 0 && tos.length == vals.length);
        // call transfer as the provided caller by using low-level call to set msg.sender
        bool reverted;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", tos, vals));
        // note: above call does not change msg.sender; to simulate different caller, the test harness
        // should invoke run from different accounts. Here we capture whether transfer reverted.
        if (ok) reverted = false; else reverted = true;
        // In the original contract, only the hard-coded owner can call successfully; so for any caller
        // other than that owner, transfer must revert. We express that rule by requiring that if msg.sender
        // is not equal to the contract's public `from` getter, then the call reverted.
        address owner = c.from();
        assert(!(msg.sender != owner) || reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] memory tos, uint[] memory v) public payable {
        // precondition: non-empty tos and caller not equal to the owner in P
        require(tos.length > 0);
        require(caller != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        // Call transfer as the specified caller by using a low-level call to set msg.sender.
        // This invokes c.transfer(...) with msg.sender == caller.
        bool reverted;
        // Perform the call from `caller` by encoding calldata and using address(c).call with msg.sender spoofing via tx.origin not allowed,
        // so we instead use the fact that test harness will externally call run; to simulate different caller, the harness should call run from that address.
        // Here we simply invoke c.transfer; the harness must ensure msg.sender of this run invocation equals `caller`.
        try c.transfer(tos, v) { reverted = false; } catch { reverted = true; }

        // The property: when caller is not the owner and tos is non-empty, transfer must revert.
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] calldata tos, uint[] calldata v) public payable {
        // ensure non-empty tos to trigger the transfer loop
        require(tos.length > 0);
        // call transfer as the provided caller using a low-level call to set msg.sender
        bool reverted;
        // perform the external call from `caller` by using call with abi.encodePacked selector
        // We use a contract call pattern: create calldata for transfer and perform call as this contract,
        // but to simulate caller we require that the provided caller is not the owner address observable via c.from()
        // Observe the owner via public getter
        address owner = c.from();
        // We only assert rule when caller != owner, because original contract only allows owner
        require(caller != owner);
        // Now invoke c.transfer(...) as this contract (msg.sender will be this contract), but the rule concerns arbitrary non-owner callers.
        // To make the test reflect calling from a non-owner, we require that caller != owner and then check that calling transfer from THIS contract reverts
        // when THIS contract's address is not the owner. Ensure this contract is not owner
        require(address(this) != owner);
        try c.transfer(tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: If the caller is not the owner, the call must revert. Here we ensure the caller is not the owner by preconditions.
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address[] memory tos, uint[] memory vals) public payable {
        // ensure we test a non-owner caller and a non-empty tos array
        require(caller != c.from());
        require(tos.length > 0);
        // perform the call as the provided caller by using a low-level call to this contract
        // we forward the call to c.transfer by performing the call from this contract; to simulate caller
        // we require that the caller parameter is the tx.origin of an external caller, so we use it only for the assertion
        // Directly invoke c.transfer and observe whether it reverts when msg.sender != owner
        bool reverted;
        try c.transfer(tos, vals) { reverted = false; } catch { reverted = true; }
        // For the original contract, any caller not equal to owner must see transfer revert when tos non-empty
        assert(reverted == true);
    }
    receive() external payable { }
}
